"use client"

import * as React from "react"

import { InviteeView } from "@/components/mockups/org-access/invitee-view"
import {
  MembersView,
  type MembersState,
} from "@/components/mockups/org-access/members-view"
import { OrganizationsView } from "@/components/mockups/org-access/organizations-view"
import { AppShell } from "@/components/shell/app-shell"
import { MockupShell } from "@/components/shell/mockup-shell"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { ORG, type InviteeState } from "@/lib/mockups/org-access-data"

const VIEWS = [
  {
    group: "Sarj",
    items: [{ id: "organizations", label: "Organizations" }],
  },
  {
    group: ORG.name,
    items: [
      { id: "members", label: "Members" },
      { id: "members-loading", label: "Members · loading" },
      { id: "members-error", label: "Members · error" },
      { id: "members-no-access", label: "Members · no access" },
    ],
  },
  {
    group: "Invited person",
    items: [
      { id: "invite", label: "Invite" },
      { id: "wrong-account", label: "Wrong account" },
      { id: "expired", label: "Link expired" },
      { id: "no-invite", label: "No invite" },
    ],
  },
] as const

type View = (typeof VIEWS)[number]["items"][number]["id"]

const MEMBERS_STATE: Partial<Record<View, MembersState>> = {
  members: "ready",
  "members-loading": "loading",
  "members-error": "error",
  "members-no-access": "no-access",
}

const INVITEE_VIEWS: View[] = [
  "invite",
  "wrong-account",
  "expired",
  "no-invite",
]

export default function OrgAccessPage() {
  const [view, setView] = React.useState<View>("members")
  const membersState = MEMBERS_STATE[view]

  return (
    <MockupShell
      title="Invite-only organization access"
      actions={
        <Select onValueChange={(next) => setView(next as View)} value={view}>
          <SelectTrigger aria-label="View" size="sm">
            <SelectValue />
          </SelectTrigger>
          <SelectContent align="end" position="popper">
            {VIEWS.map((section) => (
              <SelectGroup key={section.group}>
                <SelectLabel>{section.group}</SelectLabel>
                {section.items.map((item) => (
                  <SelectItem key={item.id} value={item.id}>
                    {item.label}
                  </SelectItem>
                ))}
              </SelectGroup>
            ))}
          </SelectContent>
        </Select>
      }
    >
      {INVITEE_VIEWS.includes(view) ? (
        <InviteeView state={view as InviteeState} />
      ) : (
        <AppShell
          active="Organizations"
          breadcrumb={
            view === "organizations"
              ? "Organizations"
              : ["Organizations", ORG.name]
          }
        >
          {membersState ? (
            // Keyed so each state starts from the same list.
            <MembersView key={view} state={membersState} />
          ) : (
            <OrganizationsView
              onOpen={(name) => {
                if (name === ORG.name) setView("members")
              }}
            />
          )}
        </AppShell>
      )}
    </MockupShell>
  )
}

"use client"

import * as React from "react"

import { HintIcon } from "@/components/design-system/icons"
import { FieldLabel } from "@/components/ui/field"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

export function FieldHint({
  children,
  className,
  hint,
  htmlFor,
}: {
  children: React.ReactNode
  /** Placement only: a horizontal `Field` needs to be told to grow this wrapper. */
  className?: string
  hint: string
  htmlFor: string
}) {
  return (
    <div className={cn("flex items-center gap-1.5", className)}>
      {/* FieldLabel, not Label, so a hinted field keeps the same line height as its neighbours. */}
      <FieldLabel htmlFor={htmlFor}>{children}</FieldLabel>
      <Tooltip>
        {/* Sized here because TooltipTrigger does not size its icon, and HugeIcons falls through to 24px. */}
        <TooltipTrigger
          aria-label={`About ${children?.toString().toLowerCase()}`}
          className="rounded-full text-muted-foreground/70 transition-colors duration-150 ease-out-cubic outline-none hover:text-foreground focus-visible:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50 motion-reduce:transition-none"
          type="button"
        >
          <HintIcon className="size-3.5" />
        </TooltipTrigger>
        <TooltipContent
          align="start"
          className="text-balance"
          side="top"
          sideOffset={4}
        >
          {hint}
        </TooltipContent>
      </Tooltip>
    </div>
  )
}

